/// A component its module exports under one name other than its own is reported under that name:
/// `export { _Card as Card }` is `Card`. The one place that names a component after an export; the exports
/// themselves are what identify it (ADR 0027). Left alone: a component with a `displayName`, one exported under
/// its own name or under several others, a sub-component (reached through a path) and one whose export name
/// another component already has.
fn name_by_the_export(&mut self, named_by_display_name: &FxHashSet<usize>) {
    let mappings = &self.data.component_mappings;
    let renames: Vec<(usize, String)> = mappings
        .iter()
        .enumerate()
        .filter(|(index, mapping)| mapping.bound && !named_by_display_name.contains(index))
        .filter_map(|(index, mapping)| {
            let mut named = mapping.exports.iter().filter(|e| e.members.is_empty() && e.name != "default");
            let (export, None) = (named.next()?, named.next()) else { return None };
            let free = mappings.iter().all(|other| other.component_name != export.name);
            (free && export.name != mapping.component_name).then(|| (index, export.name.clone()))
        })
        .collect();
    let mut taken = FxHashSet::default();
    for (index, name) in renames {
        if taken.insert(name.clone()) {
            let mapping = &mut self.data.component_mappings[index];
            mapping.local_name = Some(std::mem::replace(&mut mapping.component_name, name));
        }
    }
}

/// `import { A } from "./a"; export { A }` re-exports `A` exactly like `export { A } from "./a"`, and
/// `import * as a from "./a"; export { a as A }` like `export * as A from "./a"`; barrels and bundled typings
/// (radix-ui's) use both spellings, and only the second names a source file to follow.
fn promote_reexported_imports(&mut self) {
    for (index, local) in std::mem::take(&mut self.pending_local_exports) {
        let Some(binding) = self.data.imports.iter().find(|imp| imp.local_name.as_str() == local) else { continue };
        let crate::types::LexedExport::LocalDeclaration { name, is_type_only, .. } = &self.data.exports[index]

    }
}

/// Whether `mapping` re-binds a component the project itself declares under the same name: `const Alert =
/// InternalAlert` where `InternalAlert` is the project's `Alert`, or `const { Option } = Select` where `Select` is a
/// project component and a project component `Option` exists. An alias of a package's component is not one of these.
fn aliases_project_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> bool {
    if mapping.rule != DetectionRule::ImportedMemberAlias {
        return false;
    }
    let Some(CollectedType::TypeOf(target)) = mapping.props_type_args.first() else { return false };
    let mut ignored = Vec::new();
    let mut project = |name: &str| {
        let (file, canonical) = import::resolve_to_canonical(name, &mapping.file_path, ctx, &mut ignored)?;
        ctx.component_mapping(&file, &canonical).map(|found| found.component_name.clone())
    };
    match target.split_once('.') {
        None => project(target).is_some_and(|declared| declared == mapping.component_name),
        Some((base, _)) => {
            project(base).is_some()
                && ctx.global.component_mappings.iter().any(|other| {
                    other.rule != DetectionRule::ImportedMemberAlias && other.component_name == mapping.component_name
                })
        }
    }
}

